import * as C from './core.js';
import * as U from './ui.js';
import {Store} from './store.js';
const {h,icon,button,link,field,area,select,toggle,heading,empty}=U;
const store=new Store({apiBase:window.STALLZEIT_CONFIG.apiBase}),app=document.querySelector('#app'),modal=document.querySelector('#modal');
let view={month:C.monthKey(),expanded:new Set(),period:'month'},route='stall',register=false,inviteCode='',observer,installPrompt,report=null;
const devDemo=['localhost','127.0.0.1'].includes(location.hostname)||new URLSearchParams(location.search).get('demo')==='1';
const zone=()=>store.stable?.timezone||'Europe/Berlin',rows=kind=>store.rows.filter(x=>!kind||x.kind===kind),find=id=>store.rows.find(x=>x.id===id),admin=()=>store.stable?.role==='admin',val=(data,key)=>String(data.get(key)||'').trim(),checked=(data,key)=>data.has(key);
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),6000);}
function errorText(error){if(error.name==='AbortError')return;toast(error.message||String(error));}
function options(kind){return rows(kind).map(x=>[x.id,x.data.title]);}
function auth(){if(!inviteCode)register=false;return `<main class="auth-layout" id="main"><div class="auth-story"><a class="brand" href="#/stall"><img src="./assets/stallzeit.png" alt=""><span>Stallzeit<small>Gemeinsam. Jeden Tag.</small></span></a><div><span class="eyebrow">DEIN STALL. EUER MITEINANDER.</span><h1>Mehr Zeit <br>für das, <br><em>was zählt.</em></h1><p>Dienste fair verteilen. Gemeinsam planen.<br>Alles Wichtige für eure Pferde an einem Ort.</p><div class="auth-benefits"><span>${icon('calendar')} Ein Kalender für alle</span><span>${icon('hands')} Gemeinsam anpacken</span><span>${icon('heart')} Eure Pferde im Blick</span></div></div><p class="small">Nur Mitglieder deines Stalls haben Zugriff auf die Stallplanung.</p></div><section class="auth-form-panel"><div class="auth-form"><span class="eyebrow">WILLKOMMEN BEI STALLZEIT</span><h2>${register?'Dein Konto erstellen':'Anmelden & loslegen'}</h2><p>${inviteCode?'Du hast eine Stalleinladung erhalten. Melde dich an oder erstelle ein Konto, um beizutreten.':'Melde dich mit deinem bestehenden Stallzugang an. Neue Konten sind nur mit einer Einladung der Stallverwaltung möglich.'}</p><form id="auth-form">${register?field('Dein Name','name','','text','autocomplete="name" required maxlength="120"'):''}${field('E-Mail-Adresse','email',store.state.demo?'':store.state.user?.email||'','email','autocomplete="username" required')}${field('Passwort','password','','password',`autocomplete="${register?'new-password':'current-password'}" required ${register?'minlength="12"':''}`)}${register?'<p class="small muted">Mindestens 12 Zeichen, höchstens 72 UTF-8-Bytes.</p>':''}${toggle('Auf diesem Gerät angemeldet bleiben','remember',false)}${store.error?`<p class="error" role="alert">${h(store.error)}</p>`:''}<button class="button full" ${store.busy?'disabled':''}>${store.busy?'Wird angemeldet …':register?'Konto erstellen':'Anmelden'} ${icon('arrow')}</button></form>${inviteCode?button(register?'Du hast schon ein Konto? Anmelden':'Mit Einladung Konto erstellen','register','','text-button full'):''}<details class="server-settings"><summary>Serveradresse</summary><form id="api-form">${field('HTTPS-Adresse des Backends','apiBase',store.apiBase,'url','required')}<button class="button secondary small-button">Adresse übernehmen</button></form></details>${devDemo?button('Lokalen Beispielstall ansehen','demo','','button secondary full'):''}</div></section></main>`;}
function community(){return `<main class="community-page" id="main"><a class="brand"><img src="./assets/stallzeit.png" alt=""><span>Stallzeit</span></a>${heading('DEINE STALLGEMEINSCHAFT','Wo bist du zuhause?',store.state.stables.some(s=>s.role==='admin')?'Erstelle einen weiteren Stall oder tritt mit einer Einladung bei.':'Tritt deinem Stall mit einer gültigen Einladung bei.')}<div class="personal-grid"><section class="card"><h2>Einem Stall beitreten</h2><form id="join-form">${field('Einladungscode','code',inviteCode,'text','required autocomplete="off"')}<button class="button">Stall beitreten ${icon('arrow')}</button></form></section>${store.state.stables.some(s=>s.role==='admin')?`<section class="card"><h2>Eigenen Stall erstellen</h2><p>Als Ersteller erhältst du die Verwaltung und kannst anschließend Mitglieder einladen.</p><form id="create-stable-form">${field('Name des Stalls','name','','text','required maxlength="120"')}<button class="button secondary">Stall erstellen</button></form></section>`:''}</div>${store.state.queue.length?button('Ausstehende Änderungen prüfen','queue','','button secondary'):''}${store.state.stables.length?button('Zurück zu meinem Stall','dismiss-invite','','button secondary'):''}${button('Abmelden','logout','','text-button')}${store.error?`<p class="error">${h(store.error)}</p>`:''}</main>`;}
function archive(){const news=rows('notice').sort((a,b)=>b.updatedAt-a.updatedAt);return `${heading('ZUM NACHLESEN','Nachrichtenarchiv','Alle Meldungen bleiben hier erreichbar.',admin()?button(`${icon('plus')} Nachricht verfassen`,'new-notice'):'')}<div class="readable">${news.map(x=>`<article class="card news-item" data-notice-id="${x.id}"><span class="eyebrow">${h(C.format(x.updatedAt*1000,zone()))}</span><h2>${h(x.data.title)}</h2><p>${h(x.data.description)}</p>${admin()?button(x.data.current?'Aktuelle Nachricht bearbeiten':'Archivmeldung bearbeiten','edit-notice',`data-id="${x.id}"`,'text-button'):''}</article>`).join('')||empty('Es gibt noch keine Nachrichten.')}</div>`;}
function preference(){const p=rows('availability').find(x=>x.data.userID===store.state.user.id)?.data||{},days=p.weekdays||[1,2,3,4,5,6,7];return `${heading('PASSEND ZU DEINEM ALLTAG','Meine Verfügbarkeit','Deine Angaben bleiben privat. Bestehende Buchungen werden dadurch nicht verändert.')}<form id="availability-form" class="card readable"><h2>An diesen Tagen kann ich</h2><div class="day-options">${['Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag','Sonntag'].map((d,i)=>toggle(d,'weekdays',days.includes(i+1),`value="${i+1}"`)).join('')}</div><div class="form-grid">${field('Ab','timeFrom',p.timeFrom||'06:00','time','required')}${field('Bis','timeTo',p.timeTo||'22:00','time','required')}</div><p class="small muted">Der gesamte Dienst muss in dein Zeitfenster passen. Ohne ausgewählten Tag bist du aktuell nicht verfügbar.</p><h3>Bevorzugte Dienstarten</h3>${rows('dutyType').map(x=>toggle(x.data.title,'preferredTypeIDs',p.preferredTypeIDs?.includes(x.id),`value="${x.id}"`)).join('')}<p class="small muted">Ohne Auswahl werden alle Dienstarten berücksichtigt.</p><button class="button">Verfügbarkeit speichern</button></form>`;}
function swaps(){const requests=rows('swap').filter(x=>[x.data.userID,x.data.targetUserID].includes(store.state.user.id)),claims=rows('claim').filter(x=>x.data.userID===store.state.user.id&&Date.parse(x.data.start)>Date.now());return `${heading('BEIDSEITIG BESTÄTIGT','Diensttausch','Bis zur Zusage bleiben beide Personen für ihren bisherigen Dienst verantwortlich.')}<div class="personal-grid"><section class="card"><h2>Tauschanfragen</h2>${requests.map(r=>`<article class="swap-request"><span class="badge">${h(({open:'Offen',accepted:'Getauscht',declined:'Abgelehnt'})[r.data.status]||'Zurückgezogen')}</span><h3>${h(r.data.title||'Diensttausch')}</h3><p>${h(C.format(find(r.data.parentID)?.data.start,zone()))}<br>↔ ${h(C.format(find(r.data.targetID)?.data.start,zone()))}</p>${r.data.status==='open'?(r.data.userID===store.state.user.id?button('Anfrage zurückziehen','withdraw-swap',`data-id="${r.id}"`,'text-button danger'):`${button('Tausch prüfen','accept-swap',`data-id="${r.id}"`)} ${button('Ablehnen','decline-swap',`data-id="${r.id}"`,'text-button')}`):''}</article>`).join('')||empty('Du kannst einen deiner künftigen Dienste zum Tausch anbieten.','Keine offenen Anfragen')}</section><section class="card"><h2>Einen Dienst anbieten</h2>${claims.map(x=>button(`<span><strong>${h(x.data.title)}</strong><small>${h(C.format(x.data.start,zone()))}</small></span>${icon('swap')}`,'propose-swap',`data-id="${x.id}"`,'menu-row')).join('')||'<p>Noch keine eigenen künftigen Dienste.</p>'}</section></div>`;}
function templates(){return `${heading('PLANUNG LEICHT GEMACHT','Wochenvorlagen','Sommer-, Winter- und Feiertagspläne. Bestehende Dienste bleiben erhalten.',button(`${icon('plus')} Vorlage anlegen`,'new-template'))}<div class="suggestion-grid">${rows('weekTemplate').map(x=>`<section class="card"><span class="eyebrow">WIEDERKEHRENDE PLANUNG</span><h2>${h(x.data.title)}</h2><p>${x.data.entries?.length||0} Dienste pro Woche</p>${button('Vorschau & anwenden','apply-template',`data-id="${x.id}"`)} ${button('Bearbeiten','edit-template',`data-id="${x.id}"`,'text-button')}</section>`).join('')||empty('Speichere Dienste einer typischen Woche als Vorlage.')}</div>`;}
function management(){return `${heading('STALLVERWALTUNG','Dienste zentral planen','Dienste werden hier durch die Verwaltung angelegt.',button(`${icon('plus')} Dienst anlegen`,'new-duty'))}<section class="card">${link('Wochenvorlagen verwenden','vorlagen','book')}${link('Mitglieder & Einladungen','mitglieder','user')}</section><section class="card"><h2>Dienstarten</h2><div class="type-grid">${rows('dutyType').map(x=>button(`<strong>${h(x.data.title)}</strong><span>${h(x.data.time||'18:00')} · ${C.points(x.data.points)} P.</span>`,'edit-type',`data-id="${x.id}"`,'type-card')).join('')}${button(`${icon('plus')} Dienstart hinzufügen`,'new-type','','type-card')}</div></section><section class="card"><h2>Geplante Dienste</h2><div class="table-scroll"><table><thead><tr><th>Dienst</th><th>Beginn</th><th>Punkte</th><th>Plätze</th><th>Verwalten</th></tr></thead><tbody>${rows('duty').filter(x=>Date.parse(x.data.start)>Date.now()).map(x=>`<tr><td>${h(x.data.title)}</td><td>${h(C.format(x.data.start,zone()))}</td><td>${C.points(x.data.points)}</td><td>${C.occupancy(x,store.rows)} / ${x.data.capacity||1}</td><td>${button('Bearbeiten','edit-duty',`data-id="${x.id}"`,'text-button')} ${button('Absagen','delete-record',`data-id="${x.id}"`,'text-button danger')}</td></tr>`).join('')}</tbody></table></div></section>`;}
function members(){return `${heading('DEINE STALLGEMEINSCHAFT','Mitglieder & Einladungen','Nur angemeldete und zugeordnete Mitglieder haben Zugriff.',button(`${icon('plus')} Einladung erstellen`,'invite'))}<div class="personal-grid"><section class="card"><h2>Mitglieder</h2>${store.snap.members.filter(x=>x.active).map(m=>`<div class="member-row"><span class="avatar">${h(C.first(m.name).slice(0,1))}</span><span><strong>${h(m.name)}</strong><small>${m.role==='admin'?'Stallverwaltung':'Mitglied'}</small></span>${m.id!==store.state.user.id?`<div>${button(m.role==='admin'?'Zum Mitglied':'Zur Verwaltung','member-role',`data-id="${m.id}"`,'text-button')}${button('Zugang entziehen','member-remove',`data-id="${m.id}"`,'text-button danger')}</div>`:'<span class="badge">Du</span>'}</div>`).join('')}</section><section class="card"><h2>Aktive Einladungen</h2><p class="small muted">Ein Link ist sieben Tage gültig. Ein Widerruf sperrt weitere Beitritte über diesen Link. Bereits beigetretene Personen verwaltest du bei den Mitgliedern.</p>${(store.snap.invites||[]).map(i=>`<div class="member-row"><span>${icon('clock')}</span><span><strong>Einladung · ${h(i.id.slice(-8))}</strong><small>Gültig bis ${h(C.format(i.expiresAt*1000,zone()))}</small></span>${button('Widerrufen','revoke-invite',`data-id="${h(i.id)}"`,'text-button danger')}</div>`).join('')||'<p>Keine aktiven Einladungen.</p>'}</section></div>`;}
function settings(){const s=store.stable;return `${heading('SO WIE ES EUCH PASST','Einstellungen','Mitteilungen, Kalender und Stallverwaltung.')}<div class="personal-grid"><section class="card"><h2>Benachrichtigungen</h2><p>Auf offene Dienste, Vertretungsanfragen und Pferdestatus aufmerksam werden.</p>${button(`${icon('bell')} Browser-Mitteilungen aktivieren`,'enable-push')}${button('Browser-Mitteilungen deaktivieren','disable-push','','text-button')}<p class="small muted">Auf dem iPhone zuerst über „Teilen → Zum Home-Bildschirm“ installieren. Die Freigabe erteilst du selbst im Browser.</p>${button(`${icon('download')} Als Web-App installieren`,'install','','button secondary')}<h3>Kalenderanbindung</h3>${button('Privates Kalenderabonnement erstellen','calendar-link','','menu-row')}${button('Kalenderzugang widerrufen','calendar-revoke','','menu-row danger')}${button('Diesen Monat als Kalenderdatei exportieren','calendar-export','','menu-row')}</section><section class="card">${admin()?`<h2>Stall-Einstellungen</h2><form id="settings-form">${field('Stallname','name',s.name,'text','required maxlength="120"')}${toggle('Gemeinschaftliche Punkte sichtbar','showProgress',s.showProgress)}${[['reminders','Erinnerungen'],['changes','Änderungen & Absagen'],['openDuties','Offene Dienste & Vertretungen'],['conflicts','Buchungskonflikte']].map(([id,label])=>toggle(label,id,s.notifications[id])).join('')}<button class="button">Einstellungen speichern</button></form><div class="rule"></div><h3>Reitressourcen</h3>${rows('resource').map(x=>button(h(x.data.title),'edit-resource',`data-id="${x.id}"`,'menu-row')).join('')}${button('Reitressource hinzufügen','new-resource','','text-button')}<div class="rule"></div>${link('Änderungsverlauf','verlauf','book')}`:'<h2>Dein Zugang</h2><p>Deine Stallverwaltung pflegt Stallname, Dienstarten und Zugänge.</p>'}<div class="rule"></div><h3>Deine Daten auf diesem Gerät</h3><p class="small muted">Die letzten Stallinformationen werden lokal gespeichert, damit du sie bei Verbindungsproblemen weiter verwenden kannst. Mit der Abmeldung werden diese Daten entfernt.</p>${button('Ausstehende Änderungen prüfen','queue','','button secondary')}</section></div>`;}
function emergencyList(){return `${heading('SCHNELL ERREICHBAR','Notfallkarten','Kontakte und wichtige Hinweise je Pferd – nach dem Laden auch offline.')}<div class="horse-grid">${rows('horse').map(x=>`<section class="card"><span class="emergency-symbol">${icon('heart')}</span><h2>${h(x.data.title)}</h2>${button('Notfallkarte öffnen','emergency',`data-id="${x.id}"`,'button secondary')}</section>`).join('')||empty('Noch keine Pferde zugeordnet.')}</div>`;}
function quickView(){const next=rows('claim').find(x=>x.data.userID===store.state.user.id&&Date.parse(x.data.end)>Date.now());return `${heading('SCHNELLÜBERSICHT',store.stable.name,'Dein nächster Dienst und dein Monatssoll.')}<div class="widget-view card"><span class="eyebrow">DEIN NÄCHSTER DIENST</span><h2>${h(next?.data.title||'Noch kein Dienst geplant')}</h2>${next?`<p>${h(C.format(next.data.start,zone()))}</p>${button('Im Kalender ansehen','own-slot',`data-id="${next.id}"`,'button secondary')}`:link('Freie Dienste ansehen','dienste','calendar','button secondary')}<div class="rule"></div>${U.goalMarkup(store)}<p class="small muted">Diese Web-Schnellübersicht kann als Startbildschirm-Verknüpfung geöffnet werden. Sie ersetzt die kompakte Übersicht der früheren App.</p></div>`;}
function reportPage(){return `${heading('STALLVERWALTUNG','Monatliche Auswertung','Vergangene bestätigte Dienste und Punkte sowie Umbuchungen.')}<section class="card"><form id="report-form" class="inline-form">${field('Monat','month',C.monthKey(new Date(),zone()),'month','required')}<button class="button">Auswertung laden</button></form>${report?`<div class="table-scroll"><table><thead><tr><th>Person</th><th>Dienste</th><th>Punkte</th><th>Geplant</th><th>Umbuchungen</th></tr></thead><tbody>${report.members.map(m=>`<tr><td>${h(m.name)}</td><td>${m.duties}</td><td>${C.points(m.points)}</td><td>${m.planned}</td><td>${m.rebookings}</td></tr>`).join('')}</tbody></table></div><p class="small muted">${h(report.definition)}</p>`:'<p class="muted">Wähle einen Monat und lade die Auswertung.</p>'}</section>`;}
function render(){route=location.hash.slice(2).split('?')[0]||'stall';if(route==='einladung'){const q=new URLSearchParams(location.hash.split('?')[1]||'');inviteCode=q.get('code')||inviteCode;route='stall';}if(store.locked||!store.state.user){app.innerHTML=auth();return;}if((location.hash.startsWith('#/einladung')&&inviteCode&&!store.state.demo)||!store.state.stables.length){app.innerHTML=community();return;}if(!store.snap){app.innerHTML='<main id="main" class="loading"><p>Dein Stall wird geladen …</p>'+button('Erneut verbinden','retry')+button('Abmelden','logout','','text-button')+(store.error?`<p role="alert">${h(store.error)}</p>`:'')+'</main>';return;}
 const restricted=['vorlagen','verwaltung','mitglieder','auswertung','verlauf'];let content;if(restricted.includes(route)&&!admin())content=empty('Dieser Bereich ist der Stallverwaltung vorbehalten.','Kein Zugriff');else switch(route.split('/')[0]){case 'dienste':content=U.calendar(store,view);break;case 'meins':content=U.personal(store);break;case 'pferde':content=U.horses(store);break;case 'pferd':content=U.horseDetail(store,route.split('/')[1]);break;case 'punkte':content=U.pointsPage(store,view.period);break;case 'vorschlaege':content=U.suggestionPage(store);break;case 'verfuegbarkeit':content=preference();break;case 'tausch':content=swaps();break;case 'vorlagen':content=templates();break;case 'verwaltung':content=management();break;case 'mitglieder':content=members();break;case 'einstellungen':content=settings();break;case 'notfall':content=emergencyList();break;case 'widget':content=quickView();break;case 'archiv':content=archive();break;case 'auswertung':content=reportPage();break;case 'verlauf':content=heading('STALLVERWALTUNG','Änderungsverlauf')+'<section class="card">'+(store.snap.audits||[]).map(x=>`<p><strong>${h(x.userName)}</strong> · ${h(x.kind)} · ${h(C.format(x.createdAt*1000,zone()))}</p>`).join('')+'</section>';break;default:content=U.home(store);}
 app.innerHTML=U.shell(store,route,content);document.title=`${route==='stall'?'Stall':route==='dienste'?'Dienste & Events':route==='meins'?'Meins':'Stallzeit'} · ${store.stable.name}`;
 observer?.disconnect();observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){const notice=find(entry.target.dataset.noticeId);if(notice)store.markSeen(notice).catch(errorText);observer.unobserve(entry.target);}},{threshold:.4});app.querySelectorAll('[data-notice-id]').forEach(el=>observer.observe(el));
}
function dialog(title,body,onSubmit=null,{submit='Speichern',danger=false,wide=false}={}){modal.innerHTML=`<div class="dialog-head"><div><span class="eyebrow">STALLZEIT</span><h2 id="dialog-title">${h(title)}</h2></div>${button('×','close','aria-label="Schließen"','close-button')}</div><form id="dialog-form"><div class="dialog-content ${wide?'wide':''}">${body}</div><p class="form-error error" role="alert"></p><div class="dialog-actions">${button('Abbrechen','close','','button secondary')}${onSubmit?`<button class="button ${danger?'danger-button':''}" id="dialog-submit">${h(submit)}</button>`:''}</div></form>`;modal.classList.toggle('wide-dialog',wide);if(!modal.open)modal.showModal();modal.querySelector('form').onsubmit=async event=>{event.preventDefault();if(!onSubmit)return;const btn=modal.querySelector('#dialog-submit');btn.disabled=true;try{await onSubmit(new FormData(event.target));modal.close();}catch(error){modal.querySelector('.form-error').textContent=error.message;btn.disabled=false;}};modal.querySelector('[data-action="close"]').focus();}
function confirm(title,message,callback,{submit='Bestätigen',danger=false}={}){dialog(title,`<p>${h(message)}</p>`,callback,{submit,danger});}
function conflictMarkup(items){return items.length?`<div class="notice warning"><strong>Überschneidung in deiner Planung</strong>${items.map(x=>`<p>${h(x.data.title)} · ${h(C.format(x.data.start,zone()))}</p>`).join('')}${toggle('Ich habe die Überschneidung geprüft und möchte trotzdem buchen.','acknowledgeOverlap')}</div>`:'';}
function booking(offer,horseID){if(!offer)return;const mine=C.myBooking(offer,store.state);if(mine&&Date.parse(mine.data.start)>Date.now()){const protectedDuty=C.needsHandover(mine),open=rows('handover').find(x=>x.data.parentID===mine.id&&x.data.status==='open');dialog(protectedDuty?'Dienst abgeben?':'Buchung zurücknehmen?',`<div class="booking-summary"><span class="pill ${offer.kind}">${C.kinds[offer.kind]}</span><h3>${h(offer.data.title)}</h3><p>${h(C.format(offer.data.start,zone()))}</p>${offer.kind==='duty'?`<strong>${C.points(offer.data.points)} Punkte für dein Pferdekonto</strong>`:''}</div>${protectedDuty?`<div class="notice warning">Der Dienst beginnt innerhalb von 24 Stunden. Du bleibst verantwortlich und behältst die Punkte, bis eine andere Person verbindlich übernimmt.</div>${open?'<p>Eine Vertretung ist bereits angefragt.</p>':toggle('Andere per Push um Vertretung bitten','notify',true)}`:'<p>Möchtest du deine Buchung verbindlich zurücknehmen?</p>'}`,async data=>{if(protectedDuty){if(open)await store.submit('handover',open.data,{existing:open,action:'delete'});else await store.submit('handover',{parentID:mine.id,parentVersion:mine.version,notify:checked(data,'notify'),status:'open',title:mine.data.title,start:mine.data.start,end:mine.data.end});}else await store.cancel(mine);toast(protectedDuty?'Dein Dienst bleibt bis zur bestätigten Übernahme bei dir.':'Buchung zurückgenommen.');},{submit:protectedDuty?(open?'Anfrage zurückziehen':'Ja, Vertretung anfragen'):'Ja, abmelden',danger:!protectedDuty});return;}
 if(C.canBook(offer,store.state)){const horses=C.ownHorses(store.state),selected=horseID||horses[0]?.id||'';dialog('Anmeldung bestätigen',`<div class="booking-summary"><span class="pill ${offer.kind}">${C.kinds[offer.kind]}</span><h3>${h(offer.data.title)}</h3><p>${h(C.format(offer.data.start,zone()))}</p>${offer.kind==='duty'?`<strong>${C.points(offer.data.points)} Punkte</strong>`:''}</div>${select('Pferdekonto','horseID',horses.map(x=>[x.id,x.data.title]),selected)}${!horses.length?'<p class="error">Die Verwaltung muss dir zuerst ein Pferd zuordnen.</p>':''}<div id="booking-conflicts"></div><p class="small muted">Nach Bestätigung passt sich dein Soll sofort an. Offline bleibt die Buchung vorläufig, bis der Server sie bestätigt.</p>`,async data=>{await store.book(offer,val(data,'horseID'),checked(data,'acknowledgeOverlap'));toast('Du bist eingetragen. Dein Monatssoll wurde aktualisiert.');},{submit:'Ja, anmelden'});const update=()=>{const id=modal.querySelector('[name="horseID"]').value,conf=C.conflicts(store.rows,offer.data.start,offer.data.end,store.state.user.id,id);modal.querySelector('#booking-conflicts').innerHTML=conflictMarkup(conf);const btn=modal.querySelector('#dialog-submit');btn.disabled=!id||conf.length>0;modal.querySelector('[name="acknowledgeOverlap"]')?.addEventListener('change',e=>btn.disabled=!e.target.checked);};modal.querySelector('[name="horseID"]').onchange=update;update();return;}
 const claims=offer.kind==='arena'?[offer]:rows(offer.kind==='duty'?'claim':'registration').filter(x=>x.data.parentID===offer.id),requests=rows('handover').filter(x=>x.data.status==='open'&&claims.some(c=>c.id===x.data.parentID));dialog('Eintrag ansehen',`<h3>${h(offer.data.title)}</h3><p>${h(C.format(offer.data.start,zone()))} – ${h(C.format(offer.data.end,zone(),'time'))}</p><p>${Date.parse(offer.data.start)<=Date.now()?'Bereits begonnen oder vergangen. Änderungen sind nicht mehr möglich.':!store.state.demo&&offer.version===0?'Dieser Eintrag wird noch vom Server bestätigt.':'Dieser Eintrag ist aktuell belegt.'}</p><h3>Eingetragen</h3>${claims.map(x=>`<p>${h(U.people(store,x.data.userID))}</p>`).join('')}${requests.map(x=>button('Vertretung übernehmen','accept-handover',`data-id="${x.id}"`)).join('')}${offer.kind==='slot'&&admin()?button('Event bearbeiten','edit-event',`data-id="${offer.data.parentID}"`,'button secondary'):''}${offer.kind==='arena'&&admin()&&Date.parse(offer.data.start)>Date.now()?button('Buchung bearbeiten','edit-arena',`data-id="${offer.id}"`,'button secondary'):''}`);}
function toLocalInput(date){const p=C.parts(date,zone());return `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}`;}
function fromLocalInput(text){return C.localInstant(text.slice(0,10),text.slice(11,16),zone());}
function editor(kind,existing=null){const d=existing?.data||{},now=Date.now()+3600000,start=d.start||C.iso(now),end=d.end||C.iso(now+3600000),title=({appointment:'Event',duty:'Dienst',arena:'Reitplatzbuchung',dutyType:'Dienstart',notice:'Stallnachricht',resource:'Reitressource',horse:'Pferd'})[kind];let body='';if(!['arena'].includes(kind))body+=field('Bezeichnung','title',d.title||'','text','required maxlength="200"');if(['appointment','duty','arena'].includes(kind))body+=`<div class="form-grid">${field('Beginn','start',toLocalInput(start),'datetime-local','required')}${field('Ende','end',toLocalInput(end),'datetime-local','required')}</div>`;
 if(kind==='appointment')body+=area('Beschreibung','description',d.description||'')+field('Ort','location',d.location||'')+toggle('Gruppentermin mit Sitzungen','grouped',d.grouped??true)+field('Minuten je Sitzung','minutes',d.minutes||30,'number','min="5" max="240" step="5" required')+field('Anmeldeschluss','deadline',toLocalInput(d.deadline||C.iso(now-1800000)),'datetime-local','required');
 if(kind==='duty')body+=select('Dienstart','parentID',options('dutyType'),d.parentID||options('dutyType')[0]?.[0])+toggle('Teilbarer Dienst','shareable',d.shareable||false)+field('Plätze bei teilbarem Dienst','capacity',d.capacity||2,'number','min="2" max="100"')+(existing?'':field('Wöchentliche Angebote','repeatWeeks',1,'number','min="1" max="52"'))+field('Ort','location',d.location||'');
 if(kind==='dutyType')body+=`<div class="form-grid">${field('Standard-Uhrzeit','time',d.time||'08:00','time','required')}${field('Dauer in Minuten','minutes',d.minutes||60,'number','min="5" max="480" required')}</div><fieldset class="weight-buttons"><legend>Gewichtung</legend>${[1,2,3,4,5].map(n=>`<label><input type="radio" name="points" value="${n}" ${(d.points||1)===n?'checked':''}><span>${n}</span></label>`).join('')}</fieldset><p class="small muted">Bestehende Dienste behalten ihr bisheriges Gewicht.</p>`;
 if(kind==='arena')body+=select('Ressource','resourceID',options('resource'),d.resourceID||options('resource')[0]?.[0])+select('Pferd (optional)','horseID',[['','Ohne Pferd'],...C.ownHorses(store.state).map(x=>[x.id,x.data.title])],d.horseID||'')+'<div id="arena-conflicts"></div>';
 if(kind==='notice')body+=area('Nachricht','description',d.description||'')+toggle('Als aktuell auf der Stallseite anzeigen','current',d.current??true)+toggle('Andere per Push informieren','notify',false)+'<p class="small muted">Aktuelle News wandern 24 Stunden nach der ersten Anzeige pro Person ins Archiv.</p>';
 if(kind==='horse')body+=store.snap.members.filter(x=>x.active).map(m=>toggle(m.name,'userIDs',d.userIDs?.includes(m.id),`value="${m.id}"`)).join('')+toggle('Am gemeinsamen Monatssoll teilnehmen','participating',d.participating??true);
 dialog(`${title} ${existing?'bearbeiten':'anlegen'}`,body,async data=>{const next={};if(kind!=='arena')next.title=val(data,'title');if(['appointment','duty','arena'].includes(kind)){next.start=fromLocalInput(val(data,'start'));next.end=fromLocalInput(val(data,'end'));if(Date.parse(next.start)<=Date.now()||Date.parse(next.end)<=Date.parse(next.start))throw new Error('Beginn muss in der Zukunft und Ende nach Beginn liegen.');}
  if(kind==='appointment')Object.assign(next,{description:val(data,'description'),location:val(data,'location'),minutes:Number(data.get('minutes')),grouped:checked(data,'grouped'),deadline:fromLocalInput(val(data,'deadline'))});
  if(kind==='duty'){const type=find(val(data,'parentID'));Object.assign(next,{parentID:type?.id,shareable:checked(data,'shareable'),capacity:checked(data,'shareable')?Number(data.get('capacity')):1,repeatWeeks:existing?undefined:Number(data.get('repeatWeeks')),location:val(data,'location')});if(store.state.demo)next.points=type?.data.points;}
  if(kind==='dutyType')Object.assign(next,{time:val(data,'time'),minutes:Number(data.get('minutes')),points:Number(data.get('points'))});
  if(kind==='notice')Object.assign(next,{description:val(data,'description'),current:checked(data,'current'),notify:checked(data,'notify')});
  if(kind==='arena'){Object.assign(next,{resourceID:val(data,'resourceID'),horseID:val(data,'horseID')||undefined,acknowledgeOverlap:checked(data,'acknowledgeOverlap')});if(store.state.demo){const occupied=rows('arena').some(x=>x.id!==existing?.id&&x.data.resourceID===next.resourceID&&Date.parse(x.data.start)<Date.parse(next.end)&&Date.parse(x.data.end)>Date.parse(next.start));if(occupied)throw new Error('Der Reitplatz ist zu dieser Zeit bereits belegt.');next.title=find(next.resourceID)?.data.title;}if(C.conflicts(store.rows,next.start,next.end,store.state.user.id,next.horseID,[existing?.id]).length&&!next.acknowledgeOverlap)throw new Error('Bitte die Überschneidung prüfen und ausdrücklich bestätigen.');}
  if(kind==='horse'){next.userIDs=data.getAll('userIDs');next.participating=checked(data,'participating');if(!next.userIDs.length)throw new Error('Mindestens eine Betreuungsperson auswählen.');}
  await store.submit(kind,next,{existing});toast(`${title} gespeichert.`);
 });if(kind==='arena'){const update=()=>{try{const data=new FormData(modal.querySelector('form')),start=fromLocalInput(val(data,'start')),end=fromLocalInput(val(data,'end')),items=C.conflicts(store.rows,start,end,store.state.user.id,val(data,'horseID')||null,[existing?.id]);modal.querySelector('#arena-conflicts').innerHTML=conflictMarkup(items);}catch{}};['start','end','horseID'].forEach(name=>modal.querySelector(`[name="${name}"]`).addEventListener('change',update));update();}}
function horseNote(id){const horse=find(id),note=rows('horseStatus').find(x=>x.data.parentID===id&&x.data.userID===store.state.user.id);dialog(`${horse.data.title} · Meine Notiz`,area('Pferdestatus oder wichtige Notiz','description',note?.data.description||'','maxlength="4000"')+toggle('Andere per Push informieren','notify',false),async data=>{await store.submit('horseStatus',{parentID:id,title:horse.data.title,description:val(data,'description'),notify:checked(data,'notify')},{existing:note});toast('Pferdestatus aktualisiert.');});}
